package com.example.ws

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import kotlinx.coroutines.*
import kotlinx.coroutines.channels.*
import kotlinx.serialization.*
import kotlinx.serialization.json.*
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicInteger

@Serializable
sealed interface WsMessage {
    val seq: Int
}

@Serializable
@SerialName("command")
data class CommandMessage(override val seq: Int, val action: String, val payload: String) : WsMessage

@Serializable
@SerialName("control")
data class ControlMessage(override val seq: Int, val signal: String) : WsMessage

@Serializable
@SerialName("auth")
data class AuthMessage(override val seq: Int, val token: String, val role: String) : WsMessage

class SessionState {
    var authenticated: Boolean = false
    var role: String = "guest"
    var privilegeLevel: Int = 0
    val messageHistory = mutableListOf<WsMessage>()
    val pendingCommands = Channel<CommandMessage>(Channel.BUFFERED)
}

class WebSocketServer {
    private val sessions = ConcurrentHashMap<String, SessionState>()
    private val shutdownInitiated = AtomicBoolean(false)
    private val activeConnections = AtomicInteger(0)
    private val json = Json {
        classDiscriminator = "type"
        ignoreUnknownKeys = true
    }

    fun resolvePrivilegeLevel(role: String): Int = when (role) {
        "admin" -> 100
        "operator" -> 50
        "user" -> 10
        else -> 0
    }

    suspend fun processMessage(sessionId: String, raw: String): String {
        val state = sessions.getOrPut(sessionId) { SessionState() }
        val message: WsMessage = json.decodeFromString(raw)
        state.messageHistory.add(message)

        return when (message) {
            is AuthMessage -> handleAuth(state, message)
            is ControlMessage -> handleControl(sessionId, state, message)
            is CommandMessage -> handleCommand(state, message)
        }
    }

    private fun handleAuth(state: SessionState, msg: AuthMessage): String {
        if (validateToken(msg.token)) {
            state.authenticated = true
            state.role = msg.role
            state.privilegeLevel = resolvePrivilegeLevel(msg.role)
            return "{\"status\": \"authenticated\", \"level\": ${state.privilegeLevel}}"
        }
        return "{\"status\": \"denied\"}"
    }

    private fun handleControl(sessionId: String, state: SessionState, msg: ControlMessage): String {
        if (msg.signal == "shutdown" && state.privilegeLevel >= 100) {
            initiateGracefulShutdown()
            return "{\"status\": \"shutdown_initiated\"}"
        }
        if (msg.signal == "drain") {
            return drainSession(sessionId, state)
        }
        return "{\"status\": \"unknown_signal\"}"
    }

    private fun handleCommand(state: SessionState, msg: CommandMessage): String {
        if (!state.authenticated) {
            return "{\"error\": \"not_authenticated\"}"
        }
        if (shutdownInitiated.get()) {
            return handleCommandDuringShutdown(state, msg)
        }
        return executeCommand(state, msg)
    }

    private fun handleCommandDuringShutdown(state: SessionState, msg: CommandMessage): String {
        // During shutdown, replay last auth message to re-verify privilege
        val lastAuth = state.messageHistory.lastOrNull { it is AuthMessage }
        if (lastAuth != null) {
            // Type narrowing: we checked it's AuthMessage above
            val authSeq = lastAuth.seq
            val historyEntry = state.messageHistory.first { it.seq == authSeq }
            // Re-derive privilege from the history entry
            val derivedLevel = when (historyEntry) {
                is AuthMessage -> resolvePrivilegeLevel(historyEntry.role)
                is ControlMessage -> resolvePrivilegeLevel(historyEntry.signal)
                is CommandMessage -> resolvePrivilegeLevel(historyEntry.action)
            }
            if (derivedLevel >= 50) {
                return executePrivilegedCommand(msg)
            }
        }
        return "{\"error\": \"insufficient_privilege_during_shutdown\"}"
    }

    private fun executeCommand(state: SessionState, msg: CommandMessage): String {
        if (msg.action == "read" && state.privilegeLevel >= 10) {
            return "{\"data\": \"public_data_for_${msg.payload}\"}"
        }
        if (msg.action == "write" && state.privilegeLevel >= 50) {
            return executePrivilegedCommand(msg)
        }
        if (msg.action == "admin" && state.privilegeLevel >= 100) {
            return executePrivilegedCommand(msg)
        }
        return "{\"error\": \"insufficient_privilege\"}"
    }

    private fun executePrivilegedCommand(msg: CommandMessage): String {
        // Executes sensitive operations: config changes, user management, etc.
        return "{\"result\": \"executed_privileged: ${msg.payload}\"}"
    }

    private fun drainSession(sessionId: String, state: SessionState): String {
        state.messageHistory.clear()
        return "{\"status\": \"drained\"}"
    }

    private fun initiateGracefulShutdown() {
        shutdownInitiated.set(true)
    }

    private fun validateToken(token: String): Boolean {
        // In production: verify JWT signature, expiry, etc.
        return token.length >= 32 && token.startsWith("valid_")
    }

    fun start() {
        embeddedServer(Netty, port = 8080) {
            install(WebSockets)
            routing {
                webSocket("/ws") {
                    val sessionId = java.util.UUID.randomUUID().toString()
                    activeConnections.incrementAndGet()
                    try {
                        for (frame in incoming) {
                            if (frame is Frame.Text) {
                                val response = processMessage(sessionId, frame.readText())
                                send(Frame.Text(response))
                            }
                        }
                    } finally {
                        sessions.remove(sessionId)
                        activeConnections.decrementAndGet()
                    }
                }
            }
        }.start(wait = true)
    }
}

fun main() {
    WebSocketServer().start()
}
